package cn.mop.persistence;
import org.junit.jupiter.api.Test;
import java.util.*;import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class DeliveryReceiptMigrationTest {
 @Test void explicitV50RequiresV49AndReadOnlyDoesNotApply()throws Exception{DeliveryReceiptSchemaVerifier.resource();var mode=TestSchemaMigration.requestedMode(new String[]{"--apply-delivery-receipt-journal"});assertEquals(TestSchemaMigration.Mode.APPLY_DELIVERY_RECEIPT_JOURNAL,mode);assertTrue(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_VERSION_REGISTRATION_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.DELIVERY_RECEIPT_JOURNAL_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(TestSchemaMigration.Mode.READ_ONLY_CHECK,TestSchemaMigration.Plan.DELIVERY_RECEIPT_JOURNAL_APPLIED));assertThrows(IllegalStateException.class,()->TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_ARCHIVE_STAGING_APPLIED));}
 @Test void exactConstraintsCannotBeOmittedOrAltered(){var expected=DeliveryReceiptSchemaVerifier.CONSTRAINTS;assertEquals(19,expected.size());var changed=new TreeMap<>(expected);changed.pollFirstEntry();assertThrows(IllegalStateException.class,()->BackupVersionSchemaVerifier.requireDefinitions(expected,changed));changed.put("extra","0".repeat(64));assertThrows(IllegalStateException.class,()->BackupVersionSchemaVerifier.requireDefinitions(expected,changed));}
 @Test void sourceIsTestOnlyImmutableContiguousAndDoesNotGrantBroadUpdate()throws Exception{try(var in=getClass().getResourceAsStream("/db/migration/"+DeliveryReceiptSchemaVerifier.SCRIPT)){assertNotNull(in);String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String marker:List.of("current_database()<>'mop_test'","UNIQUE(tenant_id,command_id)","WHERE version=0","FOR UPDATE","Delivery receipt journal immutable","Contiguous original journal chain required","CHECK(NOT provider_receipt_verified)","CHECK(NOT automatic_send_enabled)","GRANT UPDATE(root_version)"))assertTrue(sql.contains(marker),marker);assertFalse(sql.contains("SECURITY DEFINER"));assertFalse(sql.contains("GRANT UPDATE ON"));assertFalse(sql.contains("GRANT DELETE"));}}
}
